import logo from './logo.svg';
import './App.css';
import { useState } from 'react';

function App() {
  const [inputValue, setInputValue] = useState("Hello World");
  const handleInput = (e) => {
    setInputValue(e.target.value);
  };
  const changeToUpperCase = () => {
    const upperCaseVal = inputValue.toUpperCase();
    setInputValue(upperCaseVal);
  }
  const changeToLowerCase = () => {
    const lowerCaseVal = inputValue.toLowerCase();
    setInputValue(lowerCaseVal);
  }
  const changeToCapitalCase = () => {
    const capitalCaseVal = inputValue.charAt(0).toUpperCase() + inputValue.slice(1);
    setInputValue(capitalCaseVal);
  }
  return (
    <div className="App">
      <input value={inputValue} onChange={(e)=> handleInput}/>
      <button onClick={changeToCapitalCase}>Click Me for Capital Case</button>
      <button onClick={changeToLowerCase}>Click Me for Lower Case</button>
      <button onClick={changeToUpperCase}>Click Me for Upper Case</button>
    </div>
  );
}

export default App;
